const e=new TextEncoder,t=new TextDecoder;export function utf8ByteLength(t){return e.encode(t).length}export function utf8Encode(t){return e.encode(t)}export function utf8Decode(e){return t.decode(e)}export function base64ToBytes(e){const t=atob(e),n=new Uint8Array(t.length);for(let e=0;e<t.length;e++)n[e]=t.charCodeAt(e);return n}export function bytesToBase64(e){let t="";for(const n of e)t+=String.fromCharCode(n);return btoa(t)}export function concatBytes(e){const t=e.reduce((e,t)=>e+t.length,0),n=new Uint8Array(t);let o=0;for(const t of e)n.set(t,o),o+=t.length;return n}